export type PrismaPromise<T> = $Public.PrismaPromise<T>


/**
 * Model User
 * Platform user — represents any authenticated principal.
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model OAuthAccount
 * Linked external identity providers (Google, Apple, etc)
 */
export type OAuthAccount = $Result.DefaultSelection<Prisma.$OAuthAccountPayload>
/**
 * Model UserProfile
 * Extended profile — kept separate to allow selective loading. Public/semi-public fields.
 */
export type UserProfile = $Result.DefaultSelection<Prisma.$UserProfilePayload>
/**
 * Model PrivacyPreference
 * User privacy and notification preferences.
 */
export type PrivacyPreference = $Result.DefaultSelection<Prisma.$PrivacyPreferencePayload>
/**
 * Model TrustProfile
 * Dynamic trust score tracking
 */
export type TrustProfile = $Result.DefaultSelection<Prisma.$TrustProfilePayload>
/**
 * Model OtpChallenge
 * OTP Authentication Challenges
 */
export type OtpChallenge = $Result.DefaultSelection<Prisma.$OtpChallengePayload>
/**
 * Model Session
 * Active user sessions
 */
export type Session = $Result.DefaultSelection<Prisma.$SessionPayload>
/**
 * Model PasswordResetToken
 * Password reset tokens
 */
export type PasswordResetToken = $Result.DefaultSelection<Prisma.$PasswordResetTokenPayload>
/**
 * Model Issue
 * A civic issue reported by a citizen or field worker.
 */
export type Issue = $Result.DefaultSelection<Prisma.$IssuePayload>
/**
 * Model VerificationHistory
 * 
 */
export type VerificationHistory = $Result.DefaultSelection<Prisma.$VerificationHistoryPayload>
/**
 * Model IssueEvidence
 * File or media evidence attached to an issue.
 */
export type IssueEvidence = $Result.DefaultSelection<Prisma.$IssueEvidencePayload>
/**
 * Model AuditLog
 * Immutable append-only audit trail.
 */
export type AuditLog = $Result.DefaultSelection<Prisma.$AuditLogPayload>
/**
 * Model AiAuditRecord
 * Immutable record of AI inferences, model governance metadata,
 * prompt/config hashes, redacted inputs, and human-in-the-loop decisions.
 */
export type AiAuditRecord = $Result.DefaultSelection<Prisma.$AiAuditRecordPayload>
/**
 * Model Jurisdiction
 * Administrative boundaries and hierarchies for routing and reporting
 */
export type Jurisdiction = $Result.DefaultSelection<Prisma.$JurisdictionPayload>
/**
 * Model JurisdictionBoundary
 * Geospatial boundary polygon and bounding box for a jurisdiction
 */
export type JurisdictionBoundary = $Result.DefaultSelection<Prisma.$JurisdictionBoundaryPayload>
/**
 * Model Organization
 * A structured body (Government, NGO, Contractor) operating within a jurisdiction
 */
export type Organization = $Result.DefaultSelection<Prisma.$OrganizationPayload>
/**
 * Model Department
 * A subdivision of an organization that handles specific categories of issues
 */
export type Department = $Result.DefaultSelection<Prisma.$DepartmentPayload>
/**
 * Model RoleAssignment
 * Represents a specific role granted to a user, optionally scoped to a jurisdiction, organization, or department.
 */
export type RoleAssignment = $Result.DefaultSelection<Prisma.$RoleAssignmentPayload>
/**
 * Model OfficialInvite
 * Invitation for a government official or contractor to join an organization/department
 */
export type OfficialInvite = $Result.DefaultSelection<Prisma.$OfficialInvitePayload>
/**
 * Model IntegrationSource
 * A data source or remote system providing data into CivIQ
 */
export type IntegrationSource = $Result.DefaultSelection<Prisma.$IntegrationSourcePayload>
/**
 * Model ExternalReference
 * Links local records (Issues, Jurisdictions, Users) to remote IDs and tracks provenance
 */
export type ExternalReference = $Result.DefaultSelection<Prisma.$ExternalReferencePayload>
/**
 * Model RiskSignal
 * Tracks suspicious patterns for human review or automated throttling without prematurely banning users
 */
export type RiskSignal = $Result.DefaultSelection<Prisma.$RiskSignalPayload>
/**
 * Model Notification
 * In-app and outbound notifications with strict idempotency
 */
export type Notification = $Result.DefaultSelection<Prisma.$NotificationPayload>

